/**
 * Asserts that every Tailwind utility the built components reference is
 * actually generated by @vcyberizadmin/theme.
 *
 * Why this exists
 * ---------------
 * A class that no longer resolves fails SILENTLY. Tailwind emits nothing, the
 * component still renders, and the styling is just quietly absent — no build
 * error, no runtime warning, nothing a unit test would catch. That is a bad
 * failure mode for a library three apps depend on.
 *
 * It is also the failure mode you hit when a token sits in a namespace Tailwind
 * does not promote to utilities. `--ease-*` becomes `ease-brand`, but there is
 * no `--duration-*` namespace, so `--duration-instant` yields no `duration-instant`
 * class unless it is declared with `@utility`. This script caught exactly that.
 *
 * How it works
 * ------------
 * Compiles the same stylesheet a consuming app would (tailwindcss + theme +
 * @source over dist), extracts utility candidates from the built output, then
 * checks each one resolves to a rule in the compiled CSS.
 *
 * Coverage limit, stated honestly: only tokens containing a `-`, `:`, `/` or `[`
 * are checked, plus the bare-word utilities allowlisted below. A bare utility
 * like `truncate` that is neither dashed nor allowlisted is skipped rather than
 * reported — this is a safety net against silent breakage, not a completeness
 * proof. Add bare words to BARE_UTILITIES as components start using them.
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const pkgRoot = fileURLToPath(new URL("..", import.meta.url));
const distDir = join(pkgRoot, "dist");
const inputCss = join(pkgRoot, "scripts", "verify-utilities.css");

/** Bare-word utilities (no dash/colon) that components legitimately use. */
const BARE_UTILITIES = new Set([
  "flex",
  "grid",
  "block",
  "inline",
  "hidden",
  "relative",
  "absolute",
  "fixed",
  "sticky",
  "truncate",
  "border",
  "rounded",
  "italic",
  "underline",
  "uppercase",
  "lowercase",
  "capitalize",
  "shadow",
  "transition",
]);

/**
 * String literals that are VALUES, not class names — directives, locales,
 * element ids. Nothing about their shape distinguishes them from a utility
 * (`main-content` looks exactly like one), so they are listed explicitly.
 * Keep this short: a long list means the heuristic is drifting and the
 * extraction rules should be tightened instead.
 */
const NOT_CLASSES = new Set([
  "use client",
  "use server",
  "en-US",
  "main-content",
  // Prop-value vocabularies compared at runtime (`polarity === "up-good"`).
  // Dashed, so they look like utilities. Both CX-TIL polarities are listed even
  // though only one currently survives into the output, so adding the other
  // comparison later does not resurrect this false positive.
  "up-good",
  "up-bad",
  // A CSS property name, used as a tailwind-merge classGroups key in lib/cn.ts.
  "font-size",
]);

/** SVG path data ("M21 12a9 9 0 0 0-9-9") tokenizes into things that look like
 *  dashed utilities. Detect and skip the whole literal. */
const SVG_PATH_DATA = /^[MmLlHhVvCcSsQqTtAaZz][\d\s.,+-]/;

/** URLs and data URIs shatter into fragments that look like dashed utilities
 *  ("data:image/svg+xml,%3Csvg", "stroke-width='2'"). Skip the whole literal. */
const URL_OR_DATA_URI = /^(data:|url\(|https?:)|:\/\//;

/** Attribute names that reach the output as string keys, not classes. */
const ATTR_PREFIX = /^(aria|data)-/;

/** `group` / `peer` (and their named forms) are markers for variants elsewhere;
 *  they emit no rule of their own, so there is nothing to look up. */
const MARKER = /^(group|peer)(\/[\w-]+)?$/;

/**
 * Raw CSS selector fragments, e.g. the joined focus-trap selector in
 * use-overlay (`a[href]`, `button:not([disabled])`). They live in string
 * literals and are shaped enough like utilities to trip the filter.
 *
 * Tailwind's own arbitrary variants start `[&`, so those are explicitly NOT
 * treated as selectors — `[&:not(:first-child)]:mt-2` is a real class and must
 * still be checked.
 */
const CSS_SELECTOR_FRAGMENT =
  /^(?!\[&)(?:[a-z]*\[[\w-]+[\]=]|[a-z]+:not\()/i;

/** Prose that happens to contain a colon, e.g. a "Consider: " label. */
const TRAILING_COLON = /:$/;

/**
 * Natural-language copy, e.g. "Immediate action · page on-call". Tailwind
 * utilities are lowercase outside of arbitrary values, so a capitalised word
 * means the literal is a sentence, not a class list — and its lowercase
 * hyphenated words ("on-call") must not be mistaken for utilities either, so
 * the WHOLE literal is skipped.
 */
function isProse(literal) {
  return /(^|\s)[A-Z]/.test(literal.replace(/\[[^\]]*\]/g, ""));
}

function walk(dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else if (entry.name.endsWith(".js")) out.push(full);
  }
  return out;
}

/** Turns a class name into the escaped form Tailwind writes into the CSS. */
function toSelector(cls) {
  return `.${cls.replace(/[.:/[\]()!%,#&>+~*'"^$=|?{}]/g, (ch) => `\\${ch}`)}`;
}

// 1. Compile exactly what a consuming app compiles.
const outFile = join(mkdtempSync(join(tmpdir(), "cyonix-verify-")), "out.css");
execFileSync(
  process.execPath,
  [
    join(pkgRoot, "node_modules", "@tailwindcss", "cli", "dist", "index.mjs"),
    "-i",
    inputCss,
    "-o",
    outFile,
  ],
  { cwd: pkgRoot, stdio: ["ignore", "ignore", "inherit"] },
);
const css = readFileSync(outFile, "utf8");

// 2. Pull candidate class names out of the built output's string literals.
const candidates = new Map(); // class -> Set<file>
for (const file of walk(distDir)) {
  const source = readFileSync(file, "utf8");
  const where = relative(pkgRoot, file);

  // Module specifiers are string literals too ("react/jsx-runtime",
  // "tailwind-merge"), and they look enough like utilities to trip the filter.
  // Collect and exclude them.
  const specifiers = new Set(
    [
      ...source.matchAll(/\bfrom\s*(["'])([^"']+)\1/g),
      ...source.matchAll(/\bimport\s*(["'])([^"']+)\1/g),
      ...source.matchAll(/\brequire\(\s*(["'])([^"']+)\1\s*\)/g),
    ].map(([, , spec]) => spec),
  );

  for (const [, , literal] of source.matchAll(
    /(["'])((?:\\.|(?!\1)[^\\\n])*)\1/g,
  )) {
    if (NOT_CLASSES.has(literal) || specifiers.has(literal)) continue;
    if (SVG_PATH_DATA.test(literal) || URL_OR_DATA_URI.test(literal)) continue;
    if (isProse(literal)) continue;
    for (const token of literal.split(/\s+/)) {
      if (!token) continue;
      const interesting = /[-:/[]/.test(token) || BARE_UTILITIES.has(token);
      if (!interesting) continue;
      // A real utility always contains a letter; SVG coordinate fragments and
      // numeric ranges do not.
      if (!/[a-z]/i.test(token)) continue;
      // Skip import specifiers, attribute names, and other path-ish literals.
      if (token.startsWith(".") || token.startsWith("@")) continue;
      if (ATTR_PREFIX.test(token) || MARKER.test(token)) continue;
      if (CSS_SELECTOR_FRAGMENT.test(token)) continue;
      if (TRAILING_COLON.test(token)) continue;
      if (!candidates.has(token)) candidates.set(token, new Set());
      candidates.get(token).add(where);
    }
  }
}

// 3. Check each candidate resolved.
const missing = [];
for (const [cls, files] of [...candidates].sort()) {
  if (!css.includes(toSelector(cls))) {
    missing.push({ cls, files: [...files] });
  }
}

if (missing.length > 0) {
  console.error(
    `\n✗ verify-utilities: ${missing.length} class(es) referenced by the ` +
      `components are NOT generated by @vcyberizadmin/theme:\n` +
      missing
        .map(({ cls, files }) => `    ${cls}\n        used in ${files.join(", ")}`)
        .join("\n") +
      `\n\n  Either the token is missing from @vcyberizadmin/theme, or it sits in a\n` +
      `  namespace Tailwind does not turn into utilities (e.g. --duration-*)\n` +
      `  and needs an explicit @utility declaration.\n`,
  );
  process.exit(1);
}

console.log(
  `✓ verify-utilities: all ${candidates.size} referenced utilities resolve`,
);
